import type { FunctionReference, FunctionReturnType } from "convex/server";
import { api as generated, type PublicApiType } from "./convex-api";

/**
 * The backend's functions, typed from the backend itself.
 *
 * `convex-api.ts` beside this file is generated by tabcake-server's `npm run api:emit` from the
 * functions its dev deployment runs, and committed here. It imports nothing from the server, so
 * this repo still builds alone. A renamed function, a changed argument or a changed return shows up
 * as a type error after the next emit, instead of as "Could not find function" at run time.
 *
 * `auth` is the one part typed by hand. Those functions belong to Convex Auth, which declares no
 * return types, so the generated file says `any` for them. They never move: the library has their
 * names written into its own code.
 */

/** A Convex Auth session as the client holds it: a 1-hour JWT and the refresh token that renews it. */
export type Tokens = { token: string; refreshToken: string };

type Empty = Record<string, never>;

export const api = generated as Omit<PublicApiType, "auth"> & {
  auth: {
    /** `{ refreshToken }` rotates a session; `{ provider, params }` starts one. */
    signIn: FunctionReference<
      "action",
      "public",
      { provider?: string; params?: Record<string, unknown>; refreshToken?: string },
      { tokens: Tokens | null }
    >;
    /** Invalidates the session behind the JWT the call is authenticated with. */
    signOut: FunctionReference<"action", "public", Empty, null>;
  };
};

/** The signed-in user. `tier` is defaulted to "free". */
export type User = NonNullable<FunctionReturnType<typeof api.users.profile.me>>;

/** A page row without its text, as `pages.queries.list` returns it. */
export type PageSummary = FunctionReturnType<typeof api.pages.queries.list>["page"][number];

/**
 * One row of `search.queries.hybrid`. Note `pageId`, where `pages.queries.list` says `_id`.
 * `relevance` orders one result set and means nothing outside it. Never shown.
 */
export type SearchResult = FunctionReturnType<typeof api.search.queries.hybrid>[number];
